import java.io.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        long count = 0;

        for (int a = 1; a <= n; a++) {
            for (int b = a; b <= n; b++) {
                int c = a ^ b;
                if (c >= b && c <= n && a + b > c) {
                    count++;
                }
            }
        }

        System.out.println(count);
    }
}

